const express = require('express');
const { IamInternalClient } = require('@infra/iam-client');
const { verifyAdminJwt } = require('./middleware');

const app = express();
app.use(express.json());

const iamClient = new IamInternalClient({
  grpcEndpoint: 'iam.internal.infra:50051',
  systemBearerToken: process.env.IAM_SYSTEM_KEY
});

app.post('/api/tenants/roles/assign', verifyAdminJwt, async (req, res) => {
  const { targetUserId, roleId, targetTenantId } = req.body;

  // Global root administrators can manage any tenant; tenant admins must be restricted to their own tenant
  const isGlobalSuperAdmin = req.user.roles.includes('GLOBAL_SUPERADMIN');
  if (!isGlobalSuperAdmin && req.user.tenantId !== targetTenantId) {
    return res.status(403).json({
      error: 'Access denied: cannot assign roles outside your own tenant organization'
    });
  }

  const response = await iamClient.assignTenantRole({
    userId: targetUserId,
    roleId,
    tenantId: targetTenantId
  });

  if (!response.success) {
    return res.status(400).json({ error: response.errorMessage });
  }

  res.json({ message: 'Role assigned successfully', assignmentId: response.assignmentId });
});

app.listen(8084);
